import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';
import { ChatRequest, ChatStreamEvent, IngestionResult } from '../models/chat.model';

@Injectable({
  providedIn: 'root',
})
export class RagApiService {
  private apiUrl = '/api';

  constructor(private http: HttpClient) {}

  health(): Observable<any> {
    return this.http.get(`${this.apiUrl}/health`);
  }

  ingest(): Observable<IngestionResult> {
    return this.http.post<IngestionResult>(`${this.apiUrl}/ingest`, {});
  }

  streamChat(request: ChatRequest): Observable<ChatStreamEvent> {
    return new Observable((observer) => {
      const eventSource = new EventSource(this.buildChatUrl(request));

      eventSource.onmessage = (event) => {
        try {
          const data = JSON.parse(event.data);
          observer.next(data);
        } catch (e) {
          observer.error(e);
        }
      };

      eventSource.onerror = () => {
        eventSource.close();
        observer.complete();
      };

      return () => {
        eventSource.close();
      };
    });
  }

  private buildChatUrl(request: ChatRequest): string {
    const params = new URLSearchParams();
    params.append('question', request.question);
    if (request.session_id) {
      params.append('session_id', request.session_id);
    }
    if (request.top_k) {
      params.append('top_k', request.top_k.toString());
    }
    if (request.filter) {
      params.append('filter', JSON.stringify(request.filter));
    }
    return `${this.apiUrl}/chat?${params.toString()}`;
  }
}
